const response = $input.first().json;
const waitItem = $('Wait 30s - Music').itemMatching(0).json;
const base = waitItem.theme ? waitItem : $('Parse AI Agent Plan').itemMatching(0).json;
const taskId = waitItem.kie_music_task_id || waitItem.data?.taskId || $('Kie Create Music').itemMatching(0).json.data.taskId;
if (!taskId) throw new Error('Kie music taskId is missing. Create response: ' + JSON.stringify($('Kie Create Music').itemMatching(0).json));
const attempt = Number(base.music_poll_attempt || 0) + 1;
const data = response?.data ?? {};
const status = data.status || 'PENDING';
const failed = ['CREATE_TASK_FAILED', 'GENERATE_AUDIO_FAILED', 'CALLBACK_EXCEPTION', 'SENSITIVE_WORD_ERROR'];
if (failed.includes(status) || data.errorCode) {
  throw new Error('Kie music failed: ' + (data.errorMessage || data.errorCode || status));
}
if (status !== 'SUCCESS') {
  if (attempt >= base.max_music_polls) {
    throw new Error('Kie music timed out after ' + attempt + ' polls. Last status: ' + status);
  }
  return [{ json: { ...base, kie_music_task_id: taskId, kie_music_status: status, music_poll_attempt: attempt, music_ready: false }, pairedItem: 0 }];
}
const tracks = data?.response?.sunoData || [];
const track = tracks.find((item) => item.audioUrl) || tracks[0];
if (!track?.audioUrl) throw new Error('Kie music succeeded but no audioUrl was returned: ' + JSON.stringify(response));
const duration = Number(track.duration || base.duration_seconds || 60);
if (duration < 10 || duration > 180) {
  throw new Error('Kie returned audio duration ' + duration + 's, but BeatAPI music-video input supports 10-180s. Regenerate a shorter track before sending to BeatAPI.');
}
return [{
  json: {
    ...base,
    kie_music_task_id: taskId,
    kie_music_status: status,
    music_poll_attempt: attempt,
    music_ready: true,
    audio_url: track.audioUrl,
    suno_audio_url: track.audioUrl,
    suno_stream_audio_url: track.streamAudioUrl,
    suno_cover_image_url: track.imageUrl,
    suno_music_id: track.id,
    suno_duration_seconds: duration,
    suno_title: track.title || base.music_title,
    suno_tags: track.tags,
  },
  pairedItem: 0,
}];

const response = $input.first().json;
const waitItem = $('Wait 20s - Image').itemMatching(0).json;
const base = waitItem.audio_url ? waitItem : $('Read Music Result').itemMatching(0).json;
const createResponse = $('Kie Create Nano Banana Image').itemMatching(0).json;
const taskId = waitItem.kie_image_task_id || waitItem.data?.taskId || createResponse.data?.taskId;
if (!taskId) throw new Error('Kie Nano Banana taskId is missing. Create response: ' + JSON.stringify(createResponse));
const attempt = Number(base.image_poll_attempt || 0) + 1;
const data = response?.data ?? {};
const state = String(data.state || data.status || 'waiting').toLowerCase();
if (state === 'fail' || data.failCode || data.errorCode) {
  throw new Error('Kie Nano Banana failed: ' + (data.failMsg || data.failCode || data.errorMessage || data.errorCode || JSON.stringify(data)));
}
if (state !== 'success') {
  if (attempt >= base.max_image_polls) {
    throw new Error('Kie Nano Banana timed out after ' + attempt + ' polls. Last state: ' + state);
  }
  return [{ json: { ...base, kie_image_task_id: taskId, kie_image_status: state, image_poll_attempt: attempt, image_ready: false }, pairedItem: 0 }];
}
let result = data.resultJson || data.response || {};
if (typeof result === 'string') {
  try {
    result = JSON.parse(result);
  } catch (error) {
    throw new Error('Kie Nano Banana returned invalid resultJson: ' + result);
  }
}
const imageUrl = (Array.isArray(result.resultUrls) ? result.resultUrls[0] : undefined)
  || (Array.isArray(result.result_urls) ? result.result_urls[0] : undefined)
  || (Array.isArray(result.urls) ? result.urls[0] : undefined)
  || (Array.isArray(result.images) ? result.images[0] : undefined)
  || result.resultImageUrl
  || result.result_url
  || result.url;
if (!imageUrl) throw new Error('Kie Nano Banana succeeded but no image URL was returned: ' + JSON.stringify(data));
return [{ json: { ...base, kie_image_task_id: taskId, kie_image_status: state, image_poll_attempt: attempt, image_ready: true, image_url: imageUrl, kie_image_url: imageUrl }, pairedItem: 0 }];

const response = $input.first().json;
const waitItem = $('Wait 10s - BeatAPI').itemMatching(0).json;
const base = waitItem.image_url ? waitItem : $('Read Nano Banana Result').itemMatching(0).json;
const createResponse = $('BeatAPI Create AIMV').itemMatching(0).json;
const taskId = waitItem.beatapi_task_id || waitItem.data?.id || createResponse.data?.id;
if (!taskId) throw new Error('BeatAPI task id is missing. Create response: ' + JSON.stringify(createResponse));
const images = [];
for (const url of [base.image_url, base.suno_cover_image_url]) {
  if (typeof url === 'string' && url.startsWith('https://') && !images.includes(url)) images.push(url);
}
const attempt = Number(base.beatapi_poll_attempt || 0) + 1;
const task = response?.data;
if (!task) throw new Error('BeatAPI poll response missing data: ' + JSON.stringify(response));
const failedStatuses = ['failed', 'canceled', 'cancelled'];
if (failedStatuses.includes(task.status)) {
  throw new Error('BeatAPI AIMV failed: ' + (task.error_message || task.error_code || JSON.stringify(task)));
}
if (task.status !== 'succeeded') {
  if (attempt >= base.max_aimv_polls) {
    throw new Error('BeatAPI AIMV timed out after ' + attempt + ' polls. Last status: ' + task.status + ', stage: ' + (task.stage || 'unknown'));
  }
  return [{ json: { ...base, beatapi_images: images.slice(0, 7), beatapi_task_id: taskId, beatapi_status: task.status, beatapi_stage: task.stage, beatapi_poll_attempt: attempt, aimv_ready: false }, pairedItem: 0 }];
}
const media = Array.isArray(task.output?.media) ? task.output.media : [];
const finalVideo = media.find((item) => item.type === 'video' && item.url) || media.find((item) => item.url);
if (!finalVideo?.url) throw new Error('BeatAPI succeeded but output.media did not include a URL: ' + JSON.stringify(task.output));
const title = String(base.youtube_title || base.music_title || 'AI Music Video').slice(0, 100);
const description = String(base.youtube_description || base.mv_prompt || '').slice(0, 4900);
const tags = Array.isArray(base.tags) ? base.tags : [];
return [{
  json: {
    ...base,
    aimv_ready: true,
    final_video_url: finalVideo.url,
    beatapi_task_id: taskId,
    beatapi_status: task.status,
    beatapi_stage: task.stage,
    beatapi_poll_attempt: attempt,
    beatapi_images: images.slice(0, 7),
    suno_audio_url: base.audio_url,
    kie_image_url: base.image_url,
    youtube_title: title,
    youtube_description: description,
    tags,
    publish_ready: {
      videoUrl: finalVideo.url,
      title,
      description,
      tags,
      suggestedPrivacyStatus: 'private'
    },
    provider_tasks: {
      kie_music_task_id: base.kie_music_task_id,
      kie_image_task_id: base.kie_image_task_id,
      beatapi_task_id: taskId
    },
    full_result: {
      beatapi_task: task,
      output_media: media,
      music: {
        audio_url: base.audio_url,
        stream_audio_url: base.suno_stream_audio_url,
        cover_image_url: base.suno_cover_image_url,
        duration_seconds: base.suno_duration_seconds
      },
      image: {
        image_url: base.image_url
      }
    }
  },
  pairedItem: 0,
}];

const response = $input.first().json;
const src = $('On form submission').itemMatching(0).json;
const pick = (...keys) => {
  for (const key of keys) {
    const value = src[key];
    if (value !== undefined && value !== null && String(value).trim() !== '') return String(value).trim();
  }
  return '';
};
const numberInRange = (value, fallback, min, max) => {
  const n = Number(value);
  if (!Number.isFinite(n)) return fallback;
  return Math.max(min, Math.min(max, Math.round(n)));
};
const enumValue = (value, allowed, fallback) => allowed.includes(value) ? value : fallback;
const input = {
  source: 'n8n-form',
  theme: pick('theme', 'Theme') || 'A cinematic neon city night drive with hopeful synthwave energy',
  genre: pick('genre', 'Genre') || 'synthwave pop instrumental',
  mood: pick('mood', 'Mood') || 'cinematic, uplifting, night city',
  visual_style: pick('visual_style', 'Visual style') || 'cinematic neon cyberpunk, high contrast, clean subject, premium music video cover art',
  audience: pick('audience', 'Audience') || 'YouTube Shorts, TikTok, Reels',
  duration_seconds: numberInRange(pick('duration_seconds', 'Duration seconds', 'duration'), 60, 10, 180),
  language: enumValue(pick('language', 'Language').toLowerCase(), ['en', 'zh'], 'en'),
  aspect_ratio: enumValue(pick('aspect_ratio', 'Aspect ratio'), ['9:16', '16:9', '1:1', '4:3', '3:4'], '9:16'),
  resolution: enumValue(pick('resolution', 'Resolution'), ['540p', '720p', '1080p'], '720p'),
  quality: enumValue(pick('quality', 'Quality'), ['standard', 'high'], 'standard'),
  kie_music_model: pick('kie_music_model') || 'V5',
  kie_image_model: pick('kie_image_model') || 'google/nano-banana',
  max_music_polls: numberInRange(pick('max_music_polls'), 30, 1, 120),
  max_image_polls: numberInRange(pick('max_image_polls'), 18, 1, 120),
  max_aimv_polls: numberInRange(pick('max_aimv_polls'), 90, 1, 240),
};
input.beatapi_language = input.language;
input.image_aspect_ratio = input.aspect_ratio;
let plan = response.output ?? response;
if (typeof plan === 'string') {
  try {
    plan = JSON.parse(plan);
  } catch (error) {
    throw new Error('AI Agent did not return valid JSON. Raw output: ' + plan);
  }
}
if (!plan || typeof plan !== 'object') {
  throw new Error('AI Agent output is missing structured plan: ' + JSON.stringify(response));
}
const trim = (value, max, fallback = '') => String(value || fallback).trim().slice(0, max);
const tags = Array.isArray(plan.tags) ? plan.tags.map((tag) => String(tag).trim()).filter(Boolean).slice(0, 12) : [];
const sunoPrompt = trim(plan.suno_prompt, 480, input.theme + ', short instrumental track');
const musicStyle = trim(plan.music_style, 900, input.genre);
const musicTitle = trim(plan.music_title, 80, 'BeatAPI AI MV');
const imagePrompt = trim(plan.image_prompt, 1800, input.visual_style) + ', no text, no captions, no watermark, clean composition, high quality music video key art';
const mvPrompt = trim(plan.mv_prompt, 3000, input.theme + ', cinematic AI music video with rhythmic camera motion');
return [{
  json: {
    ...input,
    ...plan,
    tags,
    suno_prompt: sunoPrompt,
    music_style: musicStyle,
    music_title: musicTitle,
    image_prompt: imagePrompt,
    mv_prompt: mvPrompt,
    kie_music_payload: {
      prompt: sunoPrompt + '. Target length around ' + input.duration_seconds + ' seconds.',
      customMode: true,
      instrumental: true,
      model: input.kie_music_model,
      style: musicStyle,
      title: musicTitle,
      negativeTags: 'copyrighted artist names, existing song titles, celebrity voices, speech-only audio, low quality, harsh noise'
    },
    kie_image_payload: {
      model: input.kie_image_model,
      input: {
        prompt: imagePrompt,
        output_format: 'png',
        aspect_ratio: input.image_aspect_ratio
      }
    }
  },
  pairedItem: 0,
}];
